-law-extra-check","immigration-law-decision","immigration-law-earlier-regulations"]},{"id":"where-to-file","title":"Filed no earlier than three months before planned entry, at the Latvian mission for the place of residence, or at the Office when lawfully in Latvia, by three working days before a visa held ends","evidence":["principal.residenceCountry"],"sources":["immigration-law-filing","visa-regulations","immigration-law-earlier-regulations"]}],"dependents":[],"costs":[{"id":"visa-fee","title":"State fee for examining the long-stay visa request; EUR 180 when filed less than three working days before the lawful stay in Latvia ends","kind":"fee","amount":{"op":"money","amount":9000,"currency":"EUR"},"appliesTo":"principal","sources":["state-fee-regulations"]}],"durations":[{"id":"visa","title":"The long-stay visa for remote work","min":"P0D","max":"P1Y","sources":["immigration-law-visa-term"]},{"id":"second-visa","title":"One more remote work visa may be requested; after it ends, no new long-stay visa on the same ground for six months","min":"P0D","max":"P1Y","sources":["immigration-law-visa-term"]},{"id":"decision","title":"Decision on the visa, or up to 60 days when more information or a check is needed","min":"P0D","max":"P15D","sources":["immigration-law-decision"]}],"documents":[{"id":"travel-document","title":"Valid travel document, valid at least three months beyond the visa requested, with at least two blank pages; a copy goes with a request filed at the Office online or by post","kind":"passport","appliesTo":"principal","sources":["visa-regulations","immigration-law-earlier-regulations"]},{"id":"application-form","title":"Visa application form, filled in","kind":"visa_application_form","appliesTo":"principal","sources":["visa-regulations","immigration-law-earlier-regulations"]},{"id":"photograph","title":"Photograph taken or scanned when the application is filed","kind":"photograph","appliesTo":"principal","sources":["visa-regulations","immigration-law-earl